// ========== SAFE NORMALIZATION ==========

// Ensure items array exists
if (!items || items.length === 0) {
  return [{ json: { error: "No input rows received" }}];
}

// Normalize column names safely
items.forEach(item => {
  const data = item.json || item;

  data.Parent = data.Parent || "";
  data.MonthYear = data.MonthYear || "";

  // Normalize children
  data.Child1 = data.Child1 || data.Child || data.Child_1 || "";
  data.Child2 = data.Child2 || data.Child_2 || "";
  data.Child3 = data.Child3 || "";

  // Normalize numbers
  data.ExpendHrs = Number(data.ExpendHrs || 0);
  data.WorkHrs = Number(data.WorkHrs || 0);

  // Convert Excel serial to Month-Year if needed
  if (typeof data.MonthYear === "number") {
    let excelDate = data.MonthYear;
    let jsDate = new Date((excelDate - 25569) * 86400 * 1000);
    let m = jsDate.toLocaleString('en', { month: 'short' });
    let y = jsDate.getFullYear().toString().slice(-2);
    data.MonthYear = `${m}-${y}`;
  }

  // If MonthYear like "Apr-25" or "Apr25" or "Apr 25", normalize to "Apr25"
  if (typeof data.MonthYear === "string" && data.MonthYear.length > 0) {
    const my = String(data.MonthYear).trim();
    const regex = /(?:\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b)[\s\-]*?(\d{2}|\d{4})?/i;
    const m = my.match(regex);
    if (m) {
      const mon = m[1].slice(0,3);
      let yr = m[2] ? m[2] : (new Date()).getFullYear().toString().slice(-2);
      if (yr.length === 4) yr = yr.slice(-2);
      data.MonthYear = `${mon}${yr}`;
    } else {
      const monOnly = my.match(/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b/i);
      if (monOnly) {
        let yr = (new Date()).getFullYear().toString().slice(-2);
        data.MonthYear = `${monOnly[1].slice(0,3)}${yr}`;
      }
    }
  }

  item.json = data;
});

// ========== COLLECT UNIQUE MONTHS AND SORT CHRONOLOGICALLY ==========

function monthIndex(monStr) {
  const map = { Jan:1, Feb:2, Mar:3, Apr:4, May:5, Jun:6, Jul:7, Aug:8, Sep:9, Oct:10, Nov:11, Dec:12 };
  return map[monStr.slice(0,3)] || 0;
}

const monthSet = new Set();
for (const it of items) {
  const row = it.json || it;
  if (!row.MonthYear) continue;

  const match = String(row.MonthYear).match(/(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)(\d{2})/i);
  if (match) {
    const mon = match[1].slice(0,3);
    const yy = match[2];
    monthSet.add(`${mon}${yy}`);
  }
}

const monthsArray = Array.from(monthSet).map(m => {
  const mm = m.match(/(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)(\d{2})/i);
  const mon = mm ? mm[1].slice(0,3) : "";
  const yy = mm ? mm[2] : "";
  return { label: `${mon}${yy}`, month: monthIndex(mon), year: 2000 + Number(yy) };
});

monthsArray.sort((a,b) => (a.year - b.year) || (a.month - b.month));

// Determine groups
let group1Labels = [];
let group2Label = null;

if (monthsArray.length === 0) {
  const d = new Date();
  const mon = d.toLocaleString('en', { month: 'short' }).slice(0,3);
  const yy = d.getFullYear().toString().slice(-2);
  group2Label = `${mon}${yy}`;
} else if (monthsArray.length === 1) {
  group1Labels = [];
  group2Label = monthsArray[0].label;
} else {
  group1Labels = monthsArray.slice(0, -1).map(x => x.label);
  group2Label = monthsArray[monthsArray.length - 1].label;
}

function makeLabel(arr) {
  if (!arr || arr.length === 0) return "";
  if (arr.length === 1) return arr[0];
  return `${arr[0]}-${arr[arr.length - 1]}`;
}

const group1Label = makeLabel(group1Labels);
const group2LabelFinal = group2Label;

// ========== GROUPING ==========

const groups = {};

for (const row of items.map(i => i.json)) {
  if (!row.Parent) continue;

  const childTag = row.Child1 || row.Child2 || row.Child3 || "";
  const key = row.Parent + "|" + childTag;

  if (!groups[key]) {
    groups[key] = {
      Parent: row.Parent,
      Child1: row.Child1,
      Child2: row.Child2,
      Child3: row.Child3,

      [`Planned_${group1Label}`]: 0,
      [`Planned_${group2LabelFinal}`]: 0,

      [`Actual_${group1Label}`]: 0,
      [`Actual_${group2LabelFinal}`]: 0
    };
  }

  const my = String(row.MonthYear || "");
  const isGroup2 = my === group2LabelFinal;

  if (isGroup2) {
    groups[key][`Planned_${group2LabelFinal}`] += row.ExpendHrs;
    groups[key][`Actual_${group2LabelFinal}`] += row.WorkHrs;
  } else {
    groups[key][`Planned_${group1Label}`] += row.ExpendHrs;
    groups[key][`Actual_${group1Label}`] += row.WorkHrs;
  }
}

// ========== BUILD OUTPUT WITH DEVIATION % ==========

const output = [];

function deviationPercent(actual, planned) {
  if (planned === 0) return actual === 0 ? 0 : 100;
  return ((actual - planned) / planned) * 100;
}

for (const key of Object.keys(groups)) {
  const r = groups[key];

  const plannedTotal = (r[`Planned_${group1Label}`] || 0) + (r[`Planned_${group2LabelFinal}`] || 0);
  const actualTotal = (r[`Actual_${group1Label}`] || 0) + (r[`Actual_${group2LabelFinal}`] || 0);

  let row = {
    Parent: r.Parent,
    Child1: r.Child1,
    Child2: r.Child2,
    Child3: r.Child3,
  };

  // Planned
  row[`Planned_${group1Label}`] = Number((r[`Planned_${group1Label}`] || 0).toFixed(2));
  row[`Planned_${group2LabelFinal}`] = Number((r[`Planned_${group2LabelFinal}`] || 0).toFixed(2));
  row["Planned_Total"] = Number(plannedTotal.toFixed(2));

  // Actual
  row[`Actual_${group1Label}`] = Number((r[`Actual_${group1Label}`] || 0).toFixed(2));
  row[`Actual_${group2LabelFinal}`] = Number((r[`Actual_${group2LabelFinal}`] || 0).toFixed(2));
  row["Actual_Total"] = Number(actualTotal.toFixed(2));

  // Dev
  row[`Dev_${group1Label}`] = Number(((row[`Actual_${group1Label}`] || 0) - (row[`Planned_${group1Label}`] || 0)).toFixed(2));
  row[`Dev_${group2LabelFinal}`] = Number(((row[`Actual_${group2LabelFinal}`] || 0) - (row[`Planned_${group2LabelFinal}`] || 0)).toFixed(2));
  row["Dev_Total"] = Number((actualTotal - plannedTotal).toFixed(2));

  // Dev%
  row[`Dev%_${group1Label}`] = Number(deviationPercent(row[`Actual_${group1Label}`] || 0, row[`Planned_${group1Label}`] || 0).toFixed(2));
  row[`Dev%_${group2LabelFinal}`] = Number(deviationPercent(row[`Actual_${group2LabelFinal}`] || 0, row[`Planned_${group2LabelFinal}`] || 0).toFixed(2));
 row["Dev%_Total"] = Number(
  (
    (row[`Dev%_${group1Label}`] || 0) +
    (row[`Dev%_${group2LabelFinal}`] || 0)
  ).toFixed(2)
);


  // =============================
  // REMOVE ZEROS inside this row
  // =============================
  for (const k of Object.keys(row)) {
    if (typeof row[k] === "number" && row[k] === 0) {
      row[k] = "";
    }
  }

  // Skip rows where BOTH totals are blank
  const plannedEmpty = row["Planned_Total"] === "" || row["Planned_Total"] === 0;
  const actualEmpty  = row["Actual_Total"] === ""  || row["Actual_Total"] === 0;

  if (plannedEmpty && actualEmpty) continue;

  output.push(row);
}

// =============================
// FINAL CLEANUP: remove ALL 0 values globally
// =============================
for (const row of output) {
  for (const k of Object.keys(row)) {
    if (row[k] === 0) row[k] = "";
  }
}

return output.map(o => ({ json: o }));
